  pinMode(LED, OUTPUT);
  Serial.begin(9600);
  Serial.println("=== SETUP ishga tushdi (faqat bir marta) ===");

  // isbot: setup da uch marta miltillatamiz
  for (int i = 0; i < 3; i++) {
    digitalWrite(LED, HIGH); delay(120);
    digitalWrite(LED, LOW);  delay(120);
  }
}

void loop() {
  sanoq++;
  Serial.print("loop ");
  Serial.print(sanoq);
  Serial.println("-marta bajarildi");

