}

// Uchta asosiy buyruq: pinMode, digitalWrite, delay
const int QIZIL = 7, SARIQ = 8, YASHIL = 9;   // svetofor

void setup() {
  pinMode(QIZIL, OUTPUT);
  pinMode(SARIQ, OUTPUT);
  pinMode(YASHIL, OUTPUT);
