  Serial.begin(115200);
  pinMode(LED, OUTPUT);
  WiFi.begin(WIFI_NOM, WIFI_PAROL);
  while (WiFi.status() != WL_CONNECTED) { delay(500); Serial.print("."); }
  Serial.println("\nUlandi.");
}

