    Serial.println(javob.substring(0, 200));
  } else {
    digitalWrite(LED, LOW);
    Serial.println("So'rov muvaffaqiyatsiz");
  }

  http.end();          // MAJBURIY — aloqani yopadi, aks holda xotira tugaydi
  delay(15000);
}

