#include <WiFi.h>
#define MKS 1000000ULL
RTC_DATA_ATTR int bosqich = 0;

void setup() {
  Serial.begin(115200);
  delay(500);

  Serial.println("\n=== QUVVAT REJIMLARI ===");
  Serial.println("Aktiv (WiFi yoniq): ~150-250 mA");
