    Serial.println("   light sleep dan uyg'ondik (kod shu yerdan davom etdi)");
  }

  Serial.println("\n3) DEEP SLEEP — 10 sekund");
  Serial.flush();
  esp_sleep_enable_timer_wakeup(10 * MKS);
